def get(cache, key, fetch):
    if key in cache:
        return cache[key]
    value = fetch(key)
    cache[key] = value
    return value

def make_fetch(cache):
    def fetch(key):
        cache["attempts"].append(key)
        raise TimeoutError(key)
    return fetch

